/// Local derive of `obix::MailboxTables` so that the `sqlx::query!()`
/// calls generated by the macro are compiled inside *this* crate — where
/// our `.sqlx/` offline cache lives.  The obix crate's own
/// `DefaultMailboxTables` (behind `feature = "default-tables"`) fails in
/// Nix sandbox builds because the `cargo metadata` call that sqlx uses to
/// locate `.sqlx/` returns empty output in that environment.
///
/// No `tbl_prefix` attribute → queries use the default (unprefixed) table
/// names, identical to `obix::DefaultMailboxTables`.
#[derive(Clone, obix_macros::MailboxTables)]
#[obix(crate = "obix")]
pub(super) struct LibraryMailboxTables;
